<style>
main{min-width:0}.shift-intro{margin:6px 0 0;color:#718087;font-size:12px;line-height:1.7}.shift-page{display:grid;gap:16px;min-width:0}.shift-card{background:#fff;border:1px solid #e2e8ee;border-radius:10px;padding:20px;min-width:0}.shift-card h2{font-size:16px;margin:0 0 8px}.shift-button{display:inline-flex;align-items:center;justify-content:center;padding:10px 14px;border:1px solid #ccd8e5;border-radius:7px;background:#fff;color:#334155;font:inherit;font-size:12px;font-weight:700;text-decoration:none;cursor:pointer;white-space:nowrap}.shift-button.primary{background:#1769d1;border-color:#1769d1;color:#fff}.shift-button.danger{background:#fff5f3;border-color:#f1ccc6;color:#b42318}.shift-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.shift-muted{color:#718087;font-size:11px;line-height:1.7}.shift-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}.shift-metric small{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.05em;color:#718087;font-weight:700}.shift-metric strong{display:block;font-size:23px;margin-top:8px;color:#16242b;font-variant-numeric:tabular-nums}.shift-field{display:grid;gap:6px;color:#526473;font-size:11px;font-weight:700;min-width:0}.shift-field input,.shift-field textarea,.shift-field select{width:100%;min-width:0;padding:10px 11px;border:1px solid #cdd8e3;border-radius:7px;background:#fff;font:inherit;font-weight:500;font-size:13px;color:#334155}.shift-form{display:flex;gap:14px;align-items:end;flex-wrap:wrap;margin-top:18px}.shift-form .shift-field{flex:1 1 200px}.shift-field textarea{resize:vertical}.shift-badge{display:inline-block;padding:4px 8px;font-size:10px;font-weight:700;border-radius:5px;background:#edf8ef;color:#166534}.shift-badge.closed{background:#f0f3f6;color:#667885}.shift-scroll{overflow-x:auto}.shift-table{width:100%;min-width:650px;border-collapse:collapse;font-size:12px;margin-top:16px}.shift-table th{background:#f7f9fb;color:#718087;font-size:10px;text-transform:uppercase;letter-spacing:.04em;text-align:left;padding:11px}.shift-table td{padding:13px 11px;border-bottom:1px solid #edf0f4;vertical-align:middle}.shift-table .number{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.shift-table a{color:#1057b0;text-decoration:none;font-weight:700}.shift-table small{display:block;color:#718087;font-size:10px;margin-top:4px}.shift-message{padding:12px 16px;background:#edf8ef;color:#166534;border:1px solid #c7e7ce;border-radius:8px;font-size:12px;line-height:1.7}.shift-message.error{background:#fff0ee;border-color:#f1ccc6;color:#b42318}.shift-columns{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:16px;align-items:start}.shift-close form{display:grid;gap:16px;margin-top:18px}.shift-page .shift-check{display:flex;align-items:start;gap:8px;font-size:12px;color:#526473;line-height:1.6}.shift-page .shift-check input{width:18px;height:18px;flex-shrink:0;margin-top:2px;accent-color:#1769d1}.shift-page :is(input,select,textarea,button,a):focus-visible{outline:2px solid #a7c9f4;outline-offset:2px}.shift-empty{padding:30px!important;text-align:center;color:#718087}.shift-difference{font-size:22px;font-weight:800;font-variant-numeric:tabular-nums;color:#16242b;margin:6px 0}.shift-difference.short{color:#b42318}.shift-difference.over{color:#166534}.shift-note{white-space:pre-wrap;font-size:12px;line-height:1.7;color:#526473}@media(max-width:1100px){.shift-columns{grid-template-columns:minmax(0,1fr)}.header-row{flex-wrap:wrap;gap:14px}}@media(max-width:600px){.shift-card{padding:15px}.shift-field input,.shift-field textarea,.shift-field select{font-size:16px}.shift-metric strong{font-size:20px}}
